def max_profit(prices, n):
    if n <= 1:
        return 0
    profit = 0
    for i in range(n):
        for j in range(i+1, n):
            if prices[j] > prices[i]:
                curr_profit = prices[j] - prices[i] + max_profit(prices, i)
                profit = max(profit, curr_profit)
    return profit
