def min_coins(coins, amount):
    if amount == 0:
        return 0
    res = float('inf')
    for coin in coins:
        if coin <= amount:
            sub_res = min_coins(coins, amount - coin)
            if sub_res != float('inf'):
                res = min(res, 1 + sub_res)
    return res
