def egg_drop(eggs, floors):
    if floors == 0 or floors == 1:
        return floors
    if eggs == 1:
        return floors
    min_attempts = float('inf')
    for k in range(1, floors + 1):
        res = max(egg_drop(eggs - 1, k - 1), egg_drop(eggs, floors - k))
        min_attempts = min(min_attempts, res + 1)
    return min_attempts
