def wildcard_match(s, p, m, n):
    if m == 0:
        return n == 0 or all(c == '*' for c in p[:n])
    if n == 0:
        return m == 0
    if p[n-1] == '*':
        return wildcard_match(s, p, m, n-1) or wildcard_match(s, p, m-1, n)
    if p[n-1] == '?' or s[m-1] == p[n-1]:
        return wildcard_match(s, p, m-1, n-1)
    return False
