def boolean_parenthesization(s, i, j, is_true):
    if i > j:
        return 0
    if i == j:
        if is_true:
            return 1 if s[i] == 'T' else 0
        else:
            return 1 if s[i] == 'F' else 0
    ways = 0
    for k in range(i+1, j, 2):
        lt = boolean_parenthesization(s, i, k-1, True)
        lf = boolean_parenthesization(s, i, k-1, False)
        rt = boolean_parenthesization(s, k+1, j, True)
        rf = boolean_parenthesization(s, k+1, j, False)
        if s[k] == '&':
            if is_true:
                ways += lt * rt
            else:
                ways += lt * rf + lf * rt + lf * rf
    return ways
print(boolean_parenthesization('T^F&T', 0, 4, True))

def min_jumps(arr, n, pos):
    if pos >= n - 1:
        return 0
    min_jumps_needed = float('inf')
    max_steps = arr[pos]
    for i in range(1, max_steps + 1):
        if pos + i < n:
            jumps = min_jumps(arr, n, pos + i)
            if jumps != float('inf'):
                min_jumps_needed = min(min_jumps_needed, 1 + jumps)
    return min_jumps_needed
