def min_palindrome_partition(s, i, j):
    if i >= j:
        return 0
    if s[i:j+1] == s[i:j+1][::-1]:
        return 0
    min_cuts = float('inf')
    for k in range(i, j):
        cuts = 1 + min_palindrome_partition(s, i, k) + min_palindrome_partition(s, k+1, j)
        min_cuts = min(min_cuts, cuts)
    return min_cuts
