def tsp(graph, mask, pos, n, dp):
    if mask == (1 << n) - 1:
        return graph[pos][0]
    if dp[mask][pos] != -1:
        return dp[mask][pos]
    ans = float('inf')
    for city in range(n):
        if not (mask & (1 << city)):
            new_ans = graph[pos][city] + tsp(graph, mask | (1 << city), city, n, dp)
            ans = min(ans, new_ans)
    dp[mask][pos] = ans
    return ans
