def assignment_problem(cost, n):
    dp = [[float('inf')] * (1 << n) for _ in range(n)]
    for i in range(n):
        dp[0][1 << i] = cost[0][i]
    for i in range(1, n):
        for mask in range(1 << n):
            if bin(mask).count('1') == i + 1:
                for j in range(n):
                    if mask & (1 << j):
                        dp[i][mask] = min(dp[i][mask], dp[i-1][mask ^ (1 << j)] + cost[i][j])
    return dp[n-1][(1 << n) - 1]
