def largest_independent_set(tree, n, edges):
    dp = [[0, 0] for _ in range(n)]
    def dfs(u, parent):
        dp[u][0] = 0
        dp[u][1] = 1
        for v in tree[u]:
            if v != parent:
                dfs(v, u)
                dp[u][0] += max(dp[v][0], dp[v][1])
                dp[u][1] += dp[v][0]
    tree = [[] for _ in range(n)]
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)
    dfs(0, -1)
    return max(dp[0][0], dp[0][1])
