def dp_with_divide_and_conquer(n, k, cost_func):
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    def compute(j, l, r, opt_l, opt_r):
        if l > r:
            return
        mid = (l + r) // 2
        best_cost = float('inf')
        best_k = -1
        for i in range(opt_l, min(opt_r, mid - 1) + 1):
            val = dp[i][j-1] + cost_func(i + 1, mid)
            if val < best_cost:
                best_cost = val
                best_k = i
        dp[mid][j] = best_cost
        compute(j, l, mid - 1, opt_l, best_k)
        compute(j, mid + 1, r, best_k, opt_r)
    for j in range(1, k + 1):
        compute(j, 1, n, 0, n)
    return dp[n][k]
