def convex_hull_trick(lines, queries):
    hull = []
    def intersect(l1, l2):
        m1, c1 = l1
        m2, c2 = l2
        return (c2 - c1) / (m1 - m2)
    def add_line(m, c):
        while len(hull) >= 2 and intersect(hull[-2], hull[-1]) >= intersect(hull[-1], (m, c)):
            hull.pop()
        hull.append((m, c))
    def query(x):
        while len(hull) >= 2 and hull[0][0] * x + hull[0][1] <= hull[1][0] * x + hull[1][1]:
            hull.pop(0)
        return hull[0][0] * x + hull[0][1]
    for m, c in lines:
        add_line(m, c)
    return [query(x) for x in queries]
