def dp_profile_tiling(n, m):
    if n % 2 == 1 and m % 2 == 1:
        return 0
    if n < m:
        n, m = m, n
    dp = [[0] * (1 << m) for _ in range(2)]
    dp[0][0] = 1
    cur = 0
    for i in range(n):
        for j in range(m):
            nxt = 1 - cur
            dp[nxt] = [0] * (1 << m)
            for mask in range(1 << m):
                if dp[cur][mask] == 0:
                    continue
                if mask & (1 << j):
                    dp[nxt][mask ^ (1 << j)] += dp[cur][mask]
                else:
                    if j + 1 < m and not (mask & (1 << (j + 1))):
                        dp[nxt][mask] += dp[cur][mask]
                    if i + 1 < n:
                        dp[nxt][mask | (1 << j)] += dp[cur][mask]
            cur = nxt
    return dp[cur][0]
