def maximum_bipartite_matching(graph, u_count, v_count):
    match = [-1] * v_count
    def bpm(u, seen):
        for v in graph[u]:
            if not seen[v]:
                seen[v] = True
                if match[v] == -1 or bpm(match[v], seen):
                    match[v] = u
                    return True
        return False
    result = 0
    for u in range(u_count):
        seen = [False] * v_count
        if bpm(u, seen):
            result += 1
    return result
