def min_cost_tsp_branch_and_bound(graph, n):
    min_cost = [float('inf')]
    def bound(path, current_cost):
        return current_cost
    def backtrack(path, visited, current_cost):
        if len(path) == n:
            min_cost[0] = min(min_cost[0], current_cost + graph[path[-1]][path[0]])
            return
        if bound(path, current_cost) >= min_cost[0]:
            return
        for i in range(n):
            if not visited[i]:
                new_cost = current_cost + graph[path[-1]][i] if path else 0
                if new_cost < min_cost[0]:
                    visited[i] = True
                    path.append(i)
                    backtrack(path, visited, new_cost)
                    path.pop()
                    visited[i] = False
    backtrack([0], [True] + [False] * (n-1), 0)
    return min_cost[0]
