def dp_with_cht_max(m, c, x_values):
    lines = list(zip(m, c))
    lines.sort(key=lambda l: l[0])
    hull = []
    def intersect(l1, l2):
        return (l2[1] - l1[1]) / (l1[0] - l2[0])
    def add(m_val, c_val):
        while len(hull) >= 2:
            x1 = intersect(hull[-2], hull[-1])
            x2 = intersect(hull[-1], (m_val, c_val))
            if x2 <= x1:
                hull.pop()
            else:
                break
        hull.append((m_val, c_val))
    for m_val, c_val in lines:
        add(m_val, c_val)
    def query(x):
        lo, hi = 0, len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if intersect(hull[mid], hull[mid+1]) < x:
                lo = mid + 1
            else:
                hi = mid
        return hull[lo][0] * x + hull[lo][1]
    results = []
    for x in x_values:
        results.append(query(x))
    return results
