def dp_aliens_trick(n, k, cost):
    def compute(penalty):
        dp = [float('inf')] * (n + 1)
        cnt = [0] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            for j in range(i):
                val = dp[j] + cost(j + 1, i) + penalty
                if val < dp[i]:
                    dp[i] = val
                    cnt[i] = cnt[j] + 1
        return dp[n], cnt[n]
    lo, hi = 0, 1000
    while lo < hi:
        mid = (lo + hi) // 2
        val, c = compute(mid)
        if c > k:
            lo = mid + 1
        else:
            hi = mid
    val, c = compute(lo)
    return val - lo * k
