def dp_with_fenwick_tree(arr):
    n = max(arr)
    bit = [0] * (n + 1)
    def update(idx, val):
        while idx <= n:
            bit[idx] = max(bit[idx], val)
            idx += idx & -idx
    def query(idx):
        res = 0
        while idx > 0:
            res = max(res, bit[idx])
            idx -= idx & -idx
        return res
    for x in arr:
        best = query(x - 1)
        update(x, best + 1)
    return query(n)
