def count_numbers_with_digit_sum(n_digits, sum_target):
    dp = [[[0] * 2 for _ in range(sum_target + 1)] for _ in range(n_digits + 1)]
    dp[0][0][0] = 1
    for i in range(n_digits):
        for j in range(sum_target + 1):
            for tight in range(2):
                if dp[i][j][tight] == 0:
                    continue
                limit = 9 if tight else 9
                for digit in range(limit + 1):
                    if j + digit <= sum_target:
                        dp[i+1][j+digit][tight or (digit < limit)] += dp[i][j][tight]
    return dp[n_digits][sum_target][0] + dp[n_digits][sum_target][1]
print(count_numbers_with_digit_sum(2, 5))

def dp_with_matrix_exponentiation(n):
    def mat_mul(A, B):
        MOD = 10**9 + 7
        return [[(A[0][0]*B[0][0] + A[0][1]*B[1][0]) % MOD, (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % MOD],
                [(A[1][0]*B[0][0] + A[1][1]*B[1][0]) % MOD, (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % MOD]]
    def mat_pow(M, p):
        res = [[1, 0], [0, 1]]
        while p:
            if p & 1:
                res = mat_mul(res, M)
            M = mat_mul(M, M)
            p >>= 1
        return res
    M = [[1, 1], [1, 0]]
    return mat_pow(M, n)[0][1]
