def dp_subset_cover(universe, subsets):
    n = len(universe)
    m = len(subsets)
    dp = [float('inf')] * (1 << n)
    dp[0] = 0
    mask_of_subset = []
    for s in subsets:
        mask = 0
        for elem in s:
            mask |= (1 << elem)
        mask_of_subset.append(mask)
    for mask in range(1 << n):
        for i in range(m):
            dp[mask | mask_of_subset[i]] = min(dp[mask | mask_of_subset[i]], dp[mask] + 1)
    return dp[(1 << n) - 1]
