def dp_with_monotone_queue(arr, k):
    from collections import deque
    n = len(arr)
    dp = [0] * n
    dq = deque()
    for i in range(n):
        while dq and dq[0] < i - k:
            dq.popleft()
        best = arr[i]
        if dq:
            best = max(best, dp[dq[0]] + arr[i])
        dp[i] = best
        while dq and dp[dq[-1]] <= dp[i]:
            dq.pop()
        dq.append(i)
    return max(dp)
