def dp_tree_diameter_reroot(tree, n):
    dp_down = [[0, 0] for _ in range(n)]
    diameter = [0]
    def dfs_down(u, p):
        max1 = max2 = 0
        for v in tree[u]:
            if v != p:
                dfs_down(v, u)
                val = dp_down[v][0] + 1
                if val > max1:
                    max2, max1 = max1, val
                elif val > max2:
                    max2 = val
        dp_down[u] = [max1, max2]
        diameter[0] = max(diameter[0], max1 + max2)
    dfs_down(0, -1)
    return diameter[0]
