def dp_minimum_window_subsequence(s, t):
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(1, n + 1):
        dp[0][j] = -1
    min_len = float('inf')
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i-1] == t[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = dp[i-1][j]
        if dp[i][n] != -1:
            min_len = min(min_len, i - dp[i][n])
    return min_len if min_len != float('inf') else -1
