def dp_knuth_optimization(n, cost):
    dp = [[0] * n for _ in range(n)]
    opt = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 0
        opt[i][i] = i
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = float('inf')
            for k in range(opt[i][j-1], min(opt[i+1][j], j - 1) + 1):
                val = dp[i][k] + dp[k+1][j]
                if val < dp[i][j]:
                    dp[i][j] = val
                    opt[i][j] = k
            dp[i][j] += cost(i, j)
    return dp[0][n-1]
