def dp_with_bit_trie(arr):
    max_xor = 0
    trie = {}
    def insert(num):
        node = trie
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            if bit not in node:
                node[bit] = {}
            node = node[bit]
    def query(num):
        if not trie:
            return 0
        node = trie
        xor_val = 0
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            toggled = 1 - bit
            if toggled in node:
                xor_val |= (1 << i)
                node = node[toggled]
            else:
                node = node[bit]
        return xor_val
    for x in arr:
        insert(x)
        max_xor = max(max_xor, query(x))
    return max_xor
