def dp_max_profit_with_cooldown(prices):
    n = len(prices)
    buy, sell, cool = [0] * n, [0] * n, [0] * n
    buy[0] = -prices[0]
    for i in range(1, n):
        buy[i] = max(buy[i-1], cool[i-1] - prices[i])
        sell[i] = max(sell[i-1], buy[i-1] + prices[i])
        cool[i] = max(cool[i-1], sell[i-1])
    return max(sell[n-1], cool[n-1])
