def subset_convolution(f, g, n):
    F = [[0] * (1 << n) for _ in range(n + 1)]
    G = [[0] * (1 << n) for _ in range(n + 1)]
    H = [[0] * (1 << n) for _ in range(n + 1)]
    for mask in range(1 << n):
        pop = bin(mask).count('1')
        F[pop][mask] = f[mask]
        G[pop][mask] = g[mask]
    for i in range(n + 1):
        for j in range(n):
            for mask in range(1 << n):
                if mask & (1 << j):
                    F[i][mask] += F[i][mask ^ (1 << j)]
                    G[i][mask] += G[i][mask ^ (1 << j)]
    for i in range(n + 1):
        for j in range(i + 1):
            for mask in range(1 << n):
                H[i][mask] += F[j][mask] * G[i - j][mask]
    for i in range(n + 1):
        for j in range(n):
            for mask in range(1 << n):
                if mask & (1 << j):
                    H[i][mask] -= H[i][mask ^ (1 << j)]
    res = [0] * (1 << n)
    for mask in range(1 << n):
        pop = bin(mask).count('1')
        res[mask] = H[pop][mask]
    return res
