def berlekamp_massey(s):
    n = len(s)
    C = [1]
    B = [1]
    L, m, b = 0, 1, 1
    for i in range(n):
        d = s[i]
        for j in range(1, L + 1):
            d ^= C[j] & s[i - j]
        if d == 1:
            T = C[:]
            while len(C) < len(B) + m:
                C.append(0)
            for j in range(len(B)):
                C[j + m] ^= B[j]
            if 2 * L <= i:
                L = i + 1 - L
                B = T
                m = 1
                b = d
            else:
                m += 1
        else:
            m += 1
    return C[:L + 1]
