def kitamasa(a, c, k):
    MOD = 10**9 + 7
    n = len(c)
    def combine(p, q):
        res = [0] * (2 * n + 1)
        for i in range(n + 1):
            for j in range(n + 1):
                res[i + j] = (res[i + j] + p[i] * q[j]) % MOD
        for i in range(2 * n, n, -1):
            for j in range(n):
                res[i - 1 - j] = (res[i - 1 - j] + res[i] * c[j]) % MOD
        return res[:n + 1]
    res = [1] + [0] * n
    base = [0] * (n + 1)
    base[1] = 1
    while k:
        if k & 1:
            res = combine(res, base)
        base = combine(base, base)
        k >>= 1
    ans = 0
    for i in range(n):
        ans = (ans + res[i + 1] * a[i]) % MOD
    return ans
