c = [1, 1, 0]
print(kitamasa(a, c, 5))

def dp_segtree_beats(arr, queries):
    n = len(arr)
    tree = [0] * (4 * n)
    def build(node, l, r):
        if l == r:
            tree[node] = arr[l]
            return
        mid = (l + r) // 2
        build(node * 2, l, mid)
        build(node * 2 + 1, mid + 1, r)
        tree[node] = max(tree[node * 2], tree[node * 2 + 1])
    build(1, 0, n - 1)
    def query(node, l, r, ql, qr):
        if ql > r or qr < l:
            return float('-inf')
        if ql <= l and r <= qr:
            return tree[node]
        mid = (l + r) // 2
        left = query(node * 2, l, mid, ql, qr)
        right = query(node * 2 + 1, mid + 1, r, ql, qr)
        return max(left, right)
    results = []
    for ql, qr in queries:
        results.append(query(1, 0, n - 1, ql, qr))
    return results
