def weighted_interval_scheduling(jobs):
    jobs.sort(key=lambda x: x[1])
    n = len(jobs)
    p = [0] * n
    for i in range(n):
        lo, hi = 0, i - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if jobs[mid][1] <= jobs[i][0]:
                p[i] = mid + 1
                lo = mid + 1
            else:
                hi = mid - 1
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = max(jobs[i-1][2] + dp[p[i-1]], dp[i-1])
    return dp[n]
