def dp_with_link_cut_tree(tree, queries, n):
    parent = list(range(n))
    dp = [1] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px
            dp[px] += dp[py]
    for q in queries:
        if q[0] == 'add':
            union(q[1], q[2])
    return dp[find(0)]
