def dp_count_permutations_with_forbidden_positions(n, forbidden):
    dp = [0] * (1 << n)
    dp[0] = 1
    for mask in range(1 << n):
        i = bin(mask).count('1')
        for j in range(n):
            if not (mask & (1 << j)) and (i, j) not in forbidden:
                dp[mask | (1 << j)] += dp[mask]
    return dp[(1 << n) - 1]
