    dq = deque([0])
    for i in range(1, n):
        while dq and dq[0] < i - k:
            dq.popleft()
        if dq:
            dp[i] = dp[dq[0]] + arr[i]
        while dq and dp[dq[-1]] >= dp[i]:
            dq.pop()
