def dp_on_tree_with_path_queries(tree, values, queries, n):
    depth = [0] * n
    parent = [[-1] * 20 for _ in range(n)]
    dp_sum = [0] * n
    def dfs(u, p):
        parent[u][0] = p
        dp_sum[u] = values[u] + (dp_sum[p] if p != -1 else 0)
        depth[u] = depth[p] + 1 if p != -1 else 0
        for v in tree[u]:
            if v != p:
                dfs(v, u)
    dfs(0, -1)
    for j in range(1, 20):
        for i in range(n):
            if parent[i][j-1] != -1:
                parent[i][j] = parent[parent[i][j-1]][j-1]
    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for j in range(20):
            if diff & (1 << j):
                u = parent[u][j]
        if u == v:
            return u
        for j in range(19, -1, -1):
            if parent[u][j] != parent[v][j]:
                u = parent[u][j]
                v = parent[v][j]
        return parent[u][0]
    results = []
    for u, v in queries:
        anc = lca(u, v)
        s = dp_sum[u] + dp_sum[v] - 2 * dp_sum[anc] + values[anc]
        results.append(s)
    return results
