def dp_stone_game_iii(stones):
    n = len(stones)
    dp = [float('-inf')] * (n + 1)
    dp[n] = 0
    suffix_sum = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_sum[i] = suffix_sum[i + 1] + stones[i]
    for i in range(n - 1, -1, -1):
        for k in range(1, 4):
            if i + k <= n:
                dp[i] = max(dp[i], suffix_sum[i] - dp[i + k])
    return 'Alice' if dp[0] > suffix_sum[0] - dp[0] else 'Bob' if dp[0] < suffix_sum[0] - dp[0] else 'Tie'
