def dp_count_matches_with_fft(text, pattern):
    n, m = len(text), len(pattern)
    match = [True] * (n - m + 1)
    for c in set(pattern):
        a = [1 if ch == c else 0 for ch in pattern]
        b = [1 if ch == c else 0 for ch in text]
        conv = [0] * (n + m)
        for i in range(m):
            for j in range(n):
                conv[i + j] += a[i] * b[j]
        for i in range(n - m + 1):
            if conv[i + m - 1] < pattern.count(c):
                match[i] = False
    return sum(match)
